INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92934, 'spa', 'andar en conducta (Qal)', 'Caminar metafórico en el Qal que denota conducta moral o estilo de vida: andar en los caminos de Dios, en la verdad o en el pecado. El árabe سلك (''seguir un camino'') capta la metáfora ética. Es central en la teología deuteronómica y la piedad sálmica; véanse Gn 48:15 y el motivo de la tierra seca (Éx 14:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92960, 'spa', 'andar, recorrer (Hitpael)', 'Tronco Hitpael que expresa caminar reflexivo o iterativo: pasear, ir de un lado a otro, o caminar en íntima compañía. Enoc ''caminó con Dios'' (Gn 5:22, 24), Noé igualmente (Gn 6:9), y Dios mismo pasea por el huerto (Gn 3:8). El árabe تمشّى (''pasear'') refleja este movimiento intensificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92963, 'spa', 'caminar habitualmente (Piel)', 'Tronco Piel que transmite un caminar intensivo o habitual: ir continuado, repetido o característico. Se aplica a procesiones fúnebres (Sal 38:6), al indigente que vaga en busca de pan (Job 24:10) y a patrones sostenidos de conducta (Job 31:5). La fuerza intensiva los distingue del movimiento puntual del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92978, 'spa', 'irse, partir (Qal)', 'Sentido Qal que enfatiza la partida, el alejamiento o la retirada: dejar un lugar con énfasis en la separación más que en el destino. En Oseas 6:4 y 13:3, la fidelidad ''se va'' como el rocío matutino, y en Job 16:6 el dolor no se aparta. El español se va capta bien este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93050, 'spa', 'desvanecerse, declinar', 'Uso raro que expresa el sentido de haberse ido, desvanecerse o declinar: la existencia del hablante que mengua como una sombra que se alarga. Atestiguado en Sal 109:23 (''me voy como la sombra cuando declina''). El sentido roza el ''perecer'', evocando el cognado árabe هلك (halaka, ''perecer'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93177, 'spa', 'Caminar, conducirse', 'El verbo aparece en contextos de caminar tanto literal (Dan 3:25; 4:29) como metafórico (Dan 4:37). Los hombres en el horno ''andan'' milagrosamente ilesos; Nabucodonosor ''pasea'' por su terraza y luego ''anda con soberbia''. Las traducciones multilingües captan tanto el movimiento físico como el comportamiento ético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93179, 'spa', 'Impuesto o peaje', 'Término fiscal que aparece en tres pasajes de Esdras (Esd 4:13, 20; 7:24). El contexto es la recaudación imperial persa y las exenciones para los servidores del templo. Las traducciones multilingües convergen en el campo semántico de la tributación (peaje, impuesto, contribución), reflejando el registro administrativo de la correspondencia aramea bajo dominio persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93180, 'spa', 'Brillar, resplandecer', 'Brillar o irradiar luz, dicho de luminarias y del favor divino. En el Qal (Job 29:3) representa la lámpara de Dios alumbrando la cabeza de Job como figura de bendición. En el Hifil describe el resplandor del sol, las estrellas e incluso el estornudo de Leviatán (Job 31:26; 41:18; Is 13:10). Los cognados acadio ''elelu'' y árabe ''halla'' confirman el significado raíz de luminosidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93181, 'spa', 'alabar, loar (Piel)', 'El sentido activo de alabanza en Piel: corazón litúrgico de la Biblia hebrea. Abarca el imperativo הַלְלוּ יָהּ (Aleluya), junto con todas las formas Piel que dirigen alabanza a Dios o elogian a una persona. Los Salmos del Halel (113-118) concentran este uso, mientras que 1 Crónicas lo extiende a la adoración congregacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93184, 'spa', 'jactarse, gloriarse (Hitpael)', 'Jactancia o gloria reflexiva en Hitpael: volver la exuberancia vocal hacia uno mismo. Salmo 34:2 modela la forma positiva: ''en el Señor se gloriará mi alma''. Pero 1 Reyes 20:11 advierte: ''no se gloríe el que se ciñe como el que se desciñe''. Salmos 49:6 y 52:1 describen a quienes se jactan de la riqueza y del mal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93192, 'spa', 'ser alabado (Pual)', 'Pual y Hitpael tolerativo con fuerza pasiva: ser alabado, ser digno de alabanza. El participio Pual מְהֻלָּל produce el clásico epíteto ''digno de toda alabanza'' (2 S 22:4; Sal 18:3; 48:1). Esta forma pasiva establece que la alabanza debida a Dios es un atributo objetivo, no meramente una respuesta subjetiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93206, 'spa', 'enloquecer, desatinar', 'Superposición homográfica con הלל I: enloquecer, enfurecerse, actuar insensatamente o causar locura. Eclesiastés 2:2 y 7:7 emplean formas que significan locura o enloquecimiento. Nahúm 2:4 describe carros que se lanzan furiosos por las calles. Salmo 102:8 habla de enemigos que ''se enfurecen'' contra el salmista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93223, 'spa', 'jactarse, elogiar (Piel)', 'Uso restringido del Piel donde el verbo significa jactarse o elogiar, en lugar de ofrecer alabanza doxológica. Salmo 10:3 dice que el impío ''se jacta'' del deseo de su corazón; Salmo 44:8 declara ''en Dios nos hemos gloriado todo el día''. Se distingue del sentido 2 (Hitpael) por la morfología del tronco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93250, 'spa', 'actuar como loco, fingir locura (Hitpael/Qal) — Actuar de forma demente o simula', 'actuar como loco, fingir locura (Hitpael/Qal) — Actuar de forma demente o simular locura, ya sea por trastorno genuino o por pretensión deliberada. David ''cambió su conducta'' y ''se hizo el loco'' ante Aquis (1 Sam 21:14), mientras Jeremías predice que las naciones ''enloquecerán'' al beber la copa de la ira de Dios (Jer 25:16; 50:38; 51:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93251, 'spa', 'enloquecer, volver necio (Piel) — Piel causativo', 'enloquecer, volver necio (Piel) — Piel causativo: hacer a alguien necio o volverlo loco. Dios ''enloquece'' a los adivinos invalidando sus predicciones (Is 44:25) y despoja de sensatez a los consejeros (Job 12:17). El paso de la jactancia autogenerada a la necedad impuesta por Dios marca esta forma como un binyan y sentido distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93252, 'spa', 'jactarse, ser arrogante (Qal) — Jactarse o comportarse con arrogancia, exaltándo', 'jactarse, ser arrogante (Qal) — Jactarse o comportarse con arrogancia, exaltándose con vana confianza en sí mismo. Los Salmos advierten contra ''los arrogantes'' que se yerguen ante Dios (Sal 5:5), y el salmista reprende: ''¡No os jactéis!'' (Sal 75:4). Las traducciones arrogantes e insensatos captan la dimensión moral del orgullo que raya en la necedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93260, 'spa', 'Golpear, martillar', 'Sentido primario de asestar un golpe físico: golpear, batir o martillar con fuerza. Jael clava la estaca en la sien de Sísara (Jue 5:26, junto con מָחַק y מָחַץ), los cascos machacan el campo de batalla (Jue 5:22), el salmista acepta el golpe correctivo del justo (Sal 141:5) y el Salmo 74:6 describe la destrucción de paneles tallados a hachazos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93261, 'spa', 'Vencer, tambalear', 'Sentido metafórico de ser vencido o tambalearse, no por un martillo sino por una fuerza abrumadora. Isaías 28:1 emplea el participio pasivo Qal הֲלוּמֵי para describir a los líderes de Efraín como «heridos por el vino», borrachos sin juicio. En 1 Samuel 14:16 el verbo capta el vaivén tumultuoso de un ejército que se desintegra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93270, 'spa', 'acá, aquí (adverbio de lugar) — Adverbio de lugar que significa ''acá'' (indicando', 'acá, aquí (adverbio de lugar) — Adverbio de lugar que significa ''acá'' (indicando movimiento hacia) o ''aquí'' (indicando ubicación presente). Se usa en mandatos divinos para detener el acercamiento (Éx 3:5), invitaciones a aproximarse (Rut 2:14; 1 Sam 14:36, 38), preguntas sobre cómo alguien llegó (Jue 18:3; 20:7) y la expresión temporal-figurativa ''hasta aquí'' que significa ''hasta ahora'' (2 Sam 7:18; 1 Cr 17:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93274, 'spa', 'ellos (pronombre independiente)', 'Pronombre independiente con función de sujeto o predicado: ''ellos'' o ''ellos son''. Con 497 apariciones, es el uso por defecto. Gn 3:7 (''y ellos supieron'') y Gn 6:4 (''ellos eran los poderosos'') ilustran el empleo narrativo como sujeto. La forma alterna libremente entre הֵמָּה y הֵם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93276, 'spa', 'de ellos (separativo)', 'Con מִן para expresar origen, separación o sentido partitivo: ''de ellos'', ''de entre ellos''. Lv 11:22 (''de ellos podréis comer'') muestra el uso partitivo, mientras Gn 11:6 (''nada les será vedado'') muestra la fuerza separativa. Las 99 apariciones abarcan registros legales, narrativos y proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93277, 'spa', 'a/para ellos (dativo)', 'Combinado con la preposición לְ para expresar dativo o benefactivo: ''a ellos'', ''para ellos'', ''perteneciente a ellos''. Con 146 apariciones, es la forma preposicional más frecuente. Lv 4:20 y Dt 7:5 ilustran mandatos dirigidos hacia o en beneficio de grupos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93278, 'spa', 'aquellos (demostrativo)', 'Con el artículo definido, funciona como demostrativo: ''aquellos''. Especialmente común en la fórmula temporal בַּיָּמִים הָהֵם (''en aquellos días''), que aparece numerosas veces en Reyes, Jeremías y Zacarías. Gn 6:4 y Éx 2:11 muestran esta función deíctica anclando referencias temporales narrativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93281, 'spa', 'para sí mismos (reflexivo)', 'Preposición לְ más el pronombre con sentido reflexivo o autobenefactivo: ''para sí mismos''. Jos 8:27 y 11:14 describen a Israel tomando botín ''para sí'', mientras 1 R 14:23 condena a quienes edificaron lugares altos ''para sí mismos''. El español emplea el pronombre reflexivo ''para sí''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93285, 'spa', 'como ellos (comparativo)', 'Con la preposición כְּ para expresar comparación: ''como ellos'', ''al igual que ellos''. Solo 6 apariciones, pero contextualmente expresivas. La referencia doble en 2 S 24:3 / 1 Cr 21:3 (''cien veces tantos como ellos'') y Ec 9:12 (''como ellos'' atrapados en una red) intensifican la comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93290, 'spa', 'en/con ellos (locativo)', 'Con la preposición בְּ para expresar ubicación, instrumento o medio: ''en ellos'', ''con ellos'', ''por medio de ellos''. La combinación preposicional más rara, con solo 3 apariciones. Éx 30:4 (anillos ''en ellos'' para las varas) es locativo, mientras Éx 36:1 (hábil ''por medio de ellos'') es instrumental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93303, 'spa', 'ella (variante 3fs)', 'Variante arcaica o escribal donde la forma del masculino plural sustituye al femenino singular ''ella''. Job 31:11 y Sal 73:16 conservan esta anomalía, posiblemente reflejo de convenciones dialectales u ortográficas tempranas. Este uso marginal ilumina los límites fluidos de la morfología pronominal hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93310, 'spa', 'rugir, bramar (mares/naciones) — El rugido o bramido de mares, aguas y naciones ', 'rugir, bramar (mares/naciones) — El rugido o bramido de mares, aguas y naciones en tumulto. El Salmo 46:3,6 lo emplea tanto para aguas literales como para pueblos en alboroto. Isaías 17:12 traza el paralelo explícitamente: las naciones rugen como el estruendo de muchas aguas. El verbo evoca una turbulencia profunda y envolvente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93311, 'spa', 'estar turbado, inquieto — Tumulto interior, agitación o desasosiego del alma', 'estar turbado, inquieto — Tumulto interior, agitación o desasosiego del alma. El estribillo triple de los Salmos 42-43 pregunta: ''¿Por qué te turbas, oh alma mía?'' (Sal 42:5, 42:11, 43:5). La misma raíz usada para olas embravecidas describe ahora la conmoción emocional. Jeremías 31:20 y Cantares 5:4 extienden esto a la propia compasión de Dios agitándose en su interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93312, 'spa', 'gemir, llorar de dolor — Gemir, lamentarse o aullar de dolor y angustia', 'gemir, llorar de dolor — Gemir, lamentarse o aullar de dolor y angustia. En el Salmo 55:17, el salmista gime y se lamenta en oración; en Isaías 16:11, las entrañas del profeta ''gimen como una lira'' por Moab. Isaías 59:11 compara el duelo de Israel con el gruñido de osos, mostrando cómo el dolor y el sonido animal se confunden en este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93314, 'spa', 'ser ruidoso, clamoroso — Ser bullicioso, escandaloso o clamoroso, especialmente ', 'ser ruidoso, clamoroso — Ser bullicioso, escandaloso o clamoroso, especialmente referido a personas y lugares ruidosos. Proverbios emplea esta raíz tres veces para el alboroto: el vino es ''escarnecedor'' y la cerveza ''pendenciera'' (Pr 20:1), y la ''mujer ruidosa'' de Pr 7:11 y 9:13 es הוֹמִיָּה. En 1 Reyes 1:41, la ciudad está ''alborotada'' por la fiesta de Adonías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93338, 'spa', 'ellos, a ellos (pronombre masculino plural de tercera persona) — Pronombre mascu', 'ellos, a ellos (pronombre masculino plural de tercera persona) — Pronombre masculino plural de tercera persona usado en funciones tanto nominativas (''ellos'') como acusativas (''a ellos''). Esta forma arcaica himmo es una variante del estándar hem/hemma, limitada a los libros tardíos de Esdras y Daniel. Las funciones nominativa y acusativa representan roles sintácticos de caso, no sentidos léxicos distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93340, 'spa', 'Multitud, muchedumbre', 'Multitud, muchedumbre: una multitud, muchedumbre o tropel de personas, el sentido más frecuente. Cubre poblaciones nacionales, ejércitos, asambleas reunidas o masas. Se usa del ejército arameo (1 R 20:13, 28), del pueblo restante de Jerusalén (2 R 7:13) y proféticamente de la vasta horda de Gog (Ez 39:11, 15). El árabe جُمْهُور (''tropel'') y el suajili umati (''multitud'') confirman el sentido colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93344, 'spa', 'Tumulto, alboroto', 'Tumulto, alboroto: tumulto, alboroto o conmoción, la perturbación ruidosa de una multitud, batalla o agitación social. Cuando Elí pregunta ''?Qué es este estruendo?'' al ser capturada el arca (1 Sam 4:14), o cuando Joab percibe que el tumulto amaina (1 Sam 14:19), el énfasis recae en el sonido caótico más que en el número de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93350, 'spa', 'Abundancia, riqueza', 'Abundancia, riqueza: abundancia, riqueza o plenitud, una gran cantidad de posesiones materiales o recursos, no de personas. Sal 37:16 contrasta ''lo poco del justo'' con ''la abundancia (הֲמוֹן) de muchos impíos'', y 1 Cr 29:16 habla de la ''abundancia'' de materiales preparados para el templo. El renombramiento de Abraham por Dios (Gn 17:4-5) tiende un puente entre los sentidos humano y material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93356, 'spa', 'Ruido, sonido, estruendo', 'Ruido, sonido, estruendo: un ruido, sonido o estruendo, el fenómeno auditivo en bruto, especialmente de aguas torrenciales, fuerzas retumbantes o clamor resonante. Elías oye ''el sonido de abundancia de lluvia'' (1 R 18:41), el salmista alaba a Dios que ''aquieta el estruendo de los mares'' (Sal 65:7) y Jeremías describe ''el ruido del batir de cascos'' (Jer 47:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93380, 'spa', 'Topónimo profético', 'הֲמוֹן גּוֹג — nombre profético del valle donde serán sepultados los ejércitos de Gog (Ez 39:11, 15). Se trata de una frase constructa que significa ''multitud de Gog,'' y su uso reiterado en el pasaje subraya la magnitud del enemigo derrotado. El español ''multitud de Gog'' traduce con transparencia el contenido semántico, y el topónimo funciona como monumento geográfico de la victoria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93384, 'spa', 'Confundir, derrotar, aterrorizar — Sembrar confusión, desbaratar o poner en fuga', 'Confundir, derrotar, aterrorizar — Sembrar confusión, desbaratar o poner en fuga a una fuerza enemiga, casi siempre con Dios como sujeto. El pánico es sobrenatural y total: en el Mar Rojo (Éx 14:24), en Gabaón (Jos 10:10) y en Mizpa (1 Sam 7:10), Yahvé destruye la capacidad del enemigo para organizar resistencia. Las traducciones al español ''turbó''/''derrotó'' transmiten la mezcla de terror psicológico y devastación militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93396, 'spa', 'Empujar, trillar — Empujar o impulsar con fuerza en un sentido concreto y mecáni', 'Empujar, trillar — Empujar o impulsar con fuerza en un sentido concreto y mecánico, como al pasar la rueda de trillar sobre el grano (Is 28:28). Esta única aparición conserva el núcleo físico y ruidoso de la raíz. El español ''empuja'' resalta la fisicalidad bruta, distinta del pánico abstracto del sentido dominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93400, 'spa', 'Amán (nombre propio, oficial persa)', 'Amán (nombre propio, oficial persa): nombre propio que designa exclusivamente a Amán el agagueo, antagonista del relato de Ester, quien obtuvo un decreto real para aniquilar al pueblo judío (Est 3:8-11) y fue finalmente colgado en su propia horca (Est 7:10). Las 54 ocurrencias aparecen íntegramente dentro del libro de Ester y se refieren a este único individuo en todas sus formas sintácticas: nominativo, preposicional y genitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93404, 'spa', 'Cadena o collar de honor', 'Cadena o collar de oro, específicamente la cadena honorífica otorgada como distinción real en la corte babilónica. Las seis ocurrencias aparecen en Daniel 5:7, 16 y 29, donde Belsasar promete y finalmente concede la cadena a Daniel por leer la escritura en la pared. El vocablo es un préstamo del griego μανιάκης (torques/collar), atestiguado también en arameo talmúdico y siríaco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93407, 'spa', 'Ellas (pronombre femenino plural)', 'Un pronombre femenino plural ligado que se refiere a sustantivos femeninos mencionados previamente, apareciendo siempre con una preposición prefijada. Con bet marca instrumentalidad o ubicación (''en/con ellas'', Éx 25:29; Lv 10:1), con min marca separación o comparación (''de/más que ellas'', Gn 19:29; Gn 30:26) y con kaf marca similitud (''como ellas''). El pronombre es puramente funcional, sin contenido léxico propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93413, 'spa', 'he aquí, mira', 'Interjección presentativa que significa ''¡he aquí, mira!'', dirigiendo la atención hacia un hecho o revelación dramática. Se usa en 99 de 100 ocasiones para introducir enunciados sobre los que depende una acción o conclusión (Gn 3:22; 15:3; 27:11). Especialmente frecuente en la prosa pentateucal y en los diálogos de Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93418, 'spa', 'si, acaso', 'Uso condicional o interrogativo excepcional que funciona como ''si, acaso'', introduciendo una pregunta indirecta en lugar de una declaración presentativa. Atestiguado solo en Jeremías 2:10, donde el profeta desafía a Israel a averiguar si alguna nación ha cambiado de dioses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93420, 'spa', 'si', 'La conjunción condicional ''si'', que introduce la prótasis de cláusulas condicionales en el discurso arameo. Con 12 apariciones, es el uso predeterminado en las secciones arameas de Daniel y Esdras. En Dn 2:5-9 Nabucodonosor amenaza a sus sabios con הֵן לָא (''si no''), y en Dn 3:15-18 los tres jóvenes responden con un condicional de fe: הֵן (''si'') nuestro Dios puede librarnos... הֵן לָא (''si no'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93422, 'spa', 'o, sea', 'La conjunción disyuntiva ''o, sea'', empleada en la construcción pareada הֵן ... הֵן que significa ''sea ... o''. Aparece 3 veces, todas en Esdras 7:26, donde el rey Artajerjes decreta castigo sobre los infractores: ''sea (הֵן) muerte, o (הֵן) destierro, o confiscación, o prisión''. La repetición crea una lista de alternativas, paralela a la construcción hebrea אִם ... אִם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93423, 'spa', 'Conector logico', 'Funciona como conector logico en el discurso arameo: ''por tanto'' en Dan 2:6, 9 (introduciendo una demanda) y Dan 4:27 (introduciendo un consejo). La evidencia multilingue muestra tanto el sentido inferencial (por tanto, por eso) como el condicional (tal vez, quiza). La palabra marca transiciones argumentativas en la retorica real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93424, 'spa', 'Ellas, estas (pron', 'Ellas, estas (pron. fem. pl.): pronombre o demostrativo de tercera persona femenino plural que se refiere a entidades femeninas mencionadas previamente como ''ellas'' o ''estas/aquellas''. Con 46 de 48 ocurrencias, es la función gramatical estándar. Rige plurales femeninos en material narrativo y legal: las ''hijas de los hombres'' (Gn 6:2), las siete vacas flacas (Gn 41:19, 26), los hijos de Raquel y Lea (Gn 33:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93436, 'spa', 'Aquí, he aquí', 'Aquí, he aquí: adverbio locativo o presentativo que significa ''aquí'', ''acá'' o ''he aquí'', dirigiendo la atención hacia algo presente o que se acerca. Se encuentra solo en dos pasajes: 2 Sam 4:6 (Recab y Baaná entrando en la casa) y Jer 5:6 (un leopardo acechando sus ciudades). La divergencia multilingüe es reveladora: donde el sentido pronominal produce traducciones uniformes, aquí encontramos ''und-siehe'' (alemán), ''he aquí'' (español).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93446, 'spa', 'Acá, aquí', 'Acá, aquí: deíctico espacial que dirige la atención hacia la ubicación del hablante o un destino próximo. Es el uso principal y más frecuente (44 ocurrencias). Las formas repetidas como הֵנָּה וָהֵנָּה (''de acá para allá'') transmiten movimiento de ida y vuelta (2 R 4:35). El español ''acá/aquí'' y el alemán ''hierher'' marcan consistentemente este sentido direccional (Gn 15:16; 42:15; 45:5; Jos 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93449, 'spa', 'Ahora, hasta este momento', 'Ahora, hasta este momento: extensión temporal en la que la proximidad espacial se proyecta metafóricamente sobre el tiempo, produciendo ''hasta ahora'' o ''a estas alturas''. En seis pasajes el francés distingue claramente con ''maintenant'' junto a ''ici'', mientras el español pasa a ''ahora''. Pasajes clave incluyen Gn 44:28 (''no lo he visto hasta hoy'') y 1 Sam 1:16 (''he estado derramando mi alma hasta ahora'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93453, 'spa', 'he aquí, mira', 'La partícula presentativa nuclear que significa ''he aquí, mira'': dirige la atención del oyente hacia un hecho, situación, persona o escena. Con 881 apariciones, es el sentido dominante. Desde Dios mostrando a Adán ''he aquí, os he dado toda planta'' (Gn 1:29) hasta visiones proféticas (''he aquí, una escalera'', Gn 28:12), funciona como recurso deíctico universal del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93455, 'spa', 'he aquí yo (autorreferencial)', 'הִנֵּה con sufijo de primera persona (הִנְנִי/הִנִּי) usado no como respuesta a un llamado sino como declaración autorreferencial que atrae la atención hacia la acción inminente del hablante: ''He aquí, yo voy a...''. Con 168 apariciones, predomina en el discurso divino: ''He aquí, yo traigo el diluvio'' (Gn 6:17), ''He aquí, yo enviaré enjambres de moscas'' (Éx 8:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93462, 'spa', 'aquí estoy (respuesta)', 'La fórmula de autopresentación responsiva הִנְנִי que significa ''Aquí estoy'', pronunciada exclusivamente como respuesta a un llamado directo, expresando disponibilidad, disposición y sumisión. Solo unas 12 apariciones claras, pero cada una es emblemática: Abraham ante Dios (Gn 22:1, 11), Samuel de noche (1 S 3:4-8), Moisés en la zarza (Éx 3:4) e Isaías ofreciéndose (Is 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93482, 'spa', 'Hinom', 'El nombre personal o de clan Hinom, conservado únicamente dentro de la expresión geográfica ''Valle del (hijo de) Hinom''. Funciona como término de demarcación topográfica en Josué (15:8; 18:16), como sitio de culto a Moloc y sacrificio infantil en Reyes y Crónicas (2 R 23:10; 2 Cr 28:3; 33:6), y como símbolo profético de juicio divino en Jeremías (7:31-32; 19:2, 6; 32:35). Todas las traducciones transliteran el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93483, 'spa', 'Toponimo', 'Toponimo que aparece en la retorica de conquista asiria (2 Re 18:34; 19:13; Is 37:13). Las traducciones multilingues transliteran el nombre uniformemente, reflejando su funcion como referente geografico fijo en la propaganda politica. Su ubicacion permanece desconocida, pero su funcion retorica es clara: invocar ciudades caidas para intimidar a Jerusalen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93484, 'spa', '¡Silencio! (interjección)', 'Interjección imperativa que significa «¡Silencio! ¡Calla!», exigiendo el cese inmediato de toda palabra. Las siete ocurrencias portan esta fuerza: la conspiración de Ehud contra Eglón (Jue 3:19), los entierros durante la peste (Am 6:10; 8:3), los levitas acallando a la multitud (Neh 8:11) y la orden de silencio reverente ante YHWH en los profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93488, 'spa', 'Hacer callar (Hifil)', 'Forma verbal denominativa en Hifil que significa «hacer callar, imponer silencio», atestiguada una sola vez en Nm 13:30. Caleb וַיַּהַס («hizo callar») al pueblo delante de Moisés, imponiendo quietud a una multitud presa del pánico. Es gramaticalmente notable que una interjección se conjugue como verbo Hifil pleno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93490, 'spa', 'Nifal', 'Nifal: ser cambiado, transformarse: pasivo Nifal que expresa ser cambiado o transformado de estado. Abarca la sangre que se convierte en otra sustancia (Ex 7:15-20), afecciones cutáneas que cambian de apariencia (Lv 13:3) y corazones que son alterados. El árabe تحوّل y el coreano 변하다 confirman la transformación involuntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93491, 'spa', 'Qal', 'Qal: cambiar, transformar: transformación activa en Qal: cambiar o convertir deliberadamente una cosa en otra. Dios transforma la roca en estanque de agua (Sal 114:8) y maldiciones en bendiciones (Dt 23:5). El árabe حَوَّلَ y el suajili -geuza destacan la fuerza causativa incluso en el Qal, con el agente ejerciendo control sobre el cambio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93493, 'spa', 'Qal', 'Qal: derribar, destruir: destrucción por inversión en Qal, el clásico sentido de ''destrucción'' anclado en Sodoma y Gomorra (Gn 19:21, 25, 29). El árabe قَلَبَ (voltear) y el coreano 뒤집다 (dar vuelta) evocan una inversión física total. Este sentido catastrófico se volvió proverbial, referido en Dt 29:23, Isa 13:19 y Am 4:11.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93496, 'spa', 'Nifal', 'Nifal: ser derribado: pasivo Nifal de destrucción: una ciudad o entidad destruida como si fuera volcada. Lm 4:6 compara el castigo de Jerusalén con Sodoma ''destruida en un instante''. Jon 3:4 advierte que Nínive será ''destruida''. El árabe تُقلَب y el coreano 전복되다 (ser volcado) marcan este como la contraparte pasiva del sentido 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93498, 'spa', 'Hitpael', 'Hitpael: revolverse, girar: reflexivo Hitpael: volverse, dar vueltas o girar. La espada de fuego ''que se revolvía por todos lados'' en la puerta del Edén (Gn 3:24) es la instancia paradigmática. Job 37:12 describe nubes ''que giran'' según la dirección de Dios. El árabe يتقلّب (dar vueltas) y el suajili -viringika (revolcarse) confirman el movimiento iterativo y autodirigido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93512, 'spa', 'Qal', 'Qal: trastornar (la honra): uso Qal/Nifal en Job 30:15 donde la dignidad de Job es ''trastornada'', su honra se desvanece como el viento. El español ''se volvió'' y el alemán ''der kehrte um'' sugieren un vuelco de la fortuna. Contextualmente tiende un puente entre el giro físico y la transformación metafórica, aplicados a la honra abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93519, 'spa', 'Qal', 'Qal: volverse, retroceder: giro físico intransitivo: cambiar de dirección o volverse atrás. Se distingue de los sentidos transformativos por el movimiento espacial y corporal involucrado. Aparece cuando ejércitos se vuelven en retirada (Jue 20:39, 41) o individuos se dan la vuelta (1 Sam 25:12). El árabe انصرف (partir) y el suajili -geuka (girar) confirman el sentido direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93573, 'spa', 'Qal', 'Qal: pervertir, distorsionar: sentido Qal singular en Jer 23:36 que significa pervertir o distorsionar, específicamente tergiversar las palabras del Dios viviente. El español ''trastornasteis'' capta la corrupción deliberada. Extiende la imagen de ''voltear'' al ámbito del discurso y la creencia: poner la verdad patas arriba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93581, 'spa', 'monte, montaña, cerro', 'Una masa terrestre elevada singular o pico, ya sea un monte famoso como Sinaí (Éx 19:2) o Sion, o cualquier cerro identificado por el contexto. Este es el sentido abrumadoramente dominante: cubre montes sagrados con nombre propio, posiciones elevadas en campos de batalla e imágenes poéticas de la morada de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93584, 'spa', 'montañas, montes', 'Referencia plural o colectiva a las montañas, que abarca descripciones geográficas de múltiples cumbres, apóstrofes poéticos y proféticos (''oh montes de Israel'', Ez 36:1) y pasajes donde los montes como clase responden al poder de Dios. El plural suele portar un alcance cósmico o retórico, como en ''los montes te vieron y temblaron'' (Hab 3:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93587, 'spa', 'región montañosa', 'Distrito montañoso o región de tierras altas, en lugar de una cumbre singular. Se emplea para territorios habitados como la montaña de Efraín (Jos 17:15), Judá o Seír (Gn 36:8-9). Se distingue de los sentidos 1 y 2 por el contexto: cuando har precede un nombre tribal o regional en estado constructo, designa un territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93662, 'spa', 'Hor (nombre propio, montaña/lugar) — Nombre geográfico propio que designa princi', 'Hor (nombre propio, montaña/lugar) — Nombre geográfico propio que designa principalmente el monte Hor en la frontera de Edom, sitio de la muerte de Aarón y la sucesión sacerdotal a Eleazar (Nm 20:22-29; 33:37-41), y posiblemente un segundo pico en el límite norte de Canaán (Nm 34:7-8). Las frases preposicionales que lo acompañan son sintácticas, no semánticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93668, 'spa', 'matar, dar muerte', 'El sentido activo Qal fundamental: matar, dar muerte, quitar la vida deliberadamente mediante violencia, ya sea en guerra, ejecución judicial, venganza personal o juicio divino. Domina con 146 apariciones que abarcan todos los grandes corpus narrativos, desde el temor de Caín (Gn 4:14) hasta la espada de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93690, 'spa', 'los muertos (participio pasivo)', 'Participio pasivo Qal usado como sustantivo: ''el muerto, los muertos, la víctima''. En Isaías 10:4 los muertos caen en montones; en Proverbios 7:26 las víctimas de la seductora son llamadas ''sus muertos''. Ester 9:11 informa la cuenta de los muertos en Susa. El participio cristaliza el acto violento en su resultado: los caídos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93692, 'spa', 'matador, asesino', 'Participio activo Qal como nombre de agente: ''matador, asesino''. En Génesis 4:15, Dios pone señal en Caín para que ningún ''matador'' lo hiera; en Números 31:19, los guerreros que han matado deben purificarse. Jeremías 4:31 lo usa para asesinos al acecho. Se distingue del acto de matar por su fuerza agentiva sustantivada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93703, 'spa', 'ser muerto (pasivo)', 'Formas finitas pasivas (Nifal y Qal pasivo): ''ser muerto, ser matado''. En Salmo 44:22, Israel protesta ''por tu causa somos muertos todo el día'', pasaje citado por Pablo en Romanos 8:36. Isaías 27:7 pregunta si Israel fue muerto como fueron muertos sus matadores. Lamentaciones 2:20 y Ezequiel 26:6, 15 completan estas apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93762, 'spa', 'Matanza violenta', 'Acto de matar violentamente o masacre a gran escala, ya sea en batalla o como juicio divino. Se aplica a los judíos que abaten a sus enemigos en Ester 9:5, a inocentes arrastrados a la muerte en Proverbios 24:11 y a la devastación escatológica en Isaías 30:25. El término conlleva siempre gravedad y carácter definitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93763, 'spa', 'Matanza profética', 'Matanza como símbolo profético de juicio divino y destrucción masiva. De género femenino, esta forma aparece en frases fijas: ''Valle de la Matanza'' (Jer 7:32; 19:6), ''día de matanza'' (Jer 12:3) y ''rebaño de matanza'' (Zac 11:4, 7). La capitalización en ''la Matanza'' refleja su transformación de término geográfico en emblema de retribución divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93764, 'spa', 'concebir, quedar encinta — El significado inchoativo central', 'concebir, quedar encinta — El significado inchoativo central: concebir o quedar embarazada. Domina las narrativas patriarcales con la fórmula ''y concibió y dio a luz'' (Gn 4:1; 16:4; 25:21; 38:18). Se extiende metafóricamente a concebir maldad o iniquidad (Sal 7:14; Is 59:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93769, 'spa', 'ser concebido (pasivo) — Uso pasivo donde el sujeto es el ser concebido y no la ', 'ser concebido (pasivo) — Uso pasivo donde el sujeto es el ser concebido y no la madre que concibe. Job 3:3 maldice la noche que dijo ''un varón ha sido concebido'', haciendo del niño por nacer el sujeto gramatical. Este raro uso pasivo se distingue del patrón activo predominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93771, 'spa', 'la que concibió, progenitora — Participio sustantivado que se refiere a la perso', 'la que concibió, progenitora — Participio sustantivado que se refiere a la persona que concibió, funcionando como sustantivo con el sentido de ''madre'' o ''progenitora''. En Cantares 3:4, la amada busca ''la cámara de la que me concibió'', y Oseas 2:5 habla de ''la que los concibió'' en vergüenza. El paso del verbo al sustantivo agentivo se marca en español con ''la que me concibió''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93780, 'spa', 'mujer embarazada', 'Describe el estado fisiológico de embarazo en una mujer. Se usa predicativamente en anuncios divinos de nacimiento — hinnakh harah veyoladt, ''he aquí que estás encinta y darás a luz'' (Gn 16:11; Jue 13:5, 7; cf. Is 7:14) — y en revelaciones narrativas de concepción (Gn 38:24-25; 1 S 4:19; 2 S 11:5). En el plural constructo (harot), funciona como sustantivo que designa a ''mujeres embarazadas'' como víctimas de violencia bélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93789, 'spa', 'Concepción y embarazo', 'Se refiere al acto o estado de concebir un hijo en tres contextos: la maldición tras el Edén (Gn 3:16), la concepción milagrosa de Rut (Rt 4:13) y la pérdida de bendición en Oseas (Os 9:11). El rango semántico abarca tanto el momento de la concepción como el embarazo resultante, frecuentemente en paralelo con imágenes de nacimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93796, 'spa', 'Harán (nombre propio)', 'Harán, nombre personal que probablemente significa ''montañés,'' llevado principalmente por el hijo de Taré y hermano de Abram. Este Harán engendró a Lot, Milca e Isca, pero murió prematuramente en Ur de los Caldeos (Gn 11:27-28), acontecimiento que marcó la narrativa patriarcal al colocar a Lot bajo el cuidado de Abram. Cinco de las siete ocurrencias se concentran en Génesis 11:26-31. Un segundo Harán aparece como levita gersonita (1 Cr 23:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93798, 'spa', 'derribar, demoler (Qal activo) — Derribo o demolición activa de estructuras cons', 'derribar, demoler (Qal activo) — Derribo o demolición activa de estructuras construidas: altares, muros, ciudades, en la conjugación Qal. Es el sentido principal y abarca la mayoría de las ocurrencias. Dios derriba lo que ha edificado (Lm 2:2, 17), Gedeón demolió el altar de Baal (Jue 6:25), y Elías lamenta los altares destruidos de Israel (1 R 19:10, 14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93803, 'spa', 'irrumpir, abrirse paso — Traspasar una barrera o límite para forzar la entrada, ', 'irrumpir, abrirse paso — Traspasar una barrera o límite para forzar la entrada, distinto de la demolición estructural. En Éxodo 19:21 y 19:24, el SEÑOR advierte a Moisés que el pueblo no irrumpa para mirar, un cruce peligroso de límites sagrados. El Salmo 58:6 invoca igualmente una irrupción violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93804, 'spa', 'ser derribado (Nifal) — Sentido pasivo o reflexivo en la conjugación Nifal', 'ser derribado (Nifal) — Sentido pasivo o reflexivo en la conjugación Nifal: estructuras o muros que son derribados o caen en ruinas sin agente explícito. Proverbios lo emplea para el colapso cívico: la ciudad destruida por la boca de los malvados (Pr 11:11), mientras Jeremías lo usa para los muros de Babilonia (Jer 50:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93816, 'spa', 'destruir completamente (Piel intensivo) — Demolición intensiva en la conjugación', 'destruir completamente (Piel intensivo) — Demolición intensiva en la conjugación Piel, enfatizando la exhaustividad o el papel activo de los destructores. En Éxodo 23:24, se ordena a Israel derribar por completo las estelas sagradas cananeas; en Isaías 49:17, ''tus destructores'' son quienes asolan con meticulosidad deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93833, 'spa', 'montaña, cerro — Montaña o cerro como elevación geográfica física, usado en regi', 'montaña, cerro — Montaña o cerro como elevación geográfica física, usado en registros poéticos y elevados junto al más común har. Aparece en contextos de majestad divina (Sal 36:6), descripción geográfica (Dt 8:9) e imaginería profética. El vocablo porta el mismo significado central que har —un relieve elevado— sin que la evidencia de traducción justifique subdivisiones semánticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93845, 'spa', 'Gentilicio guerrero davídico', 'Designación gentilicia que identifica a ciertos guerreros en la compañía de valientes de David. Se aplica a Sama (2 Sam 23:11, 33; 1 Cr 11:34) y a Ahiam (2 Sam 23:33; 1 Cr 11:35). La etimología podría derivar de הַר (''montaña''), sugiriendo un origen serrano. Las traducciones al español ofrecen tanto ''el hararita'' como ''el ararita'', reflejando vacilación en la transcripción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93849, 'spa', 'Oficial de la corte', 'Hatac, un servidor de la corte persa que transmitio mensajes entre Ester y Mardoqueo durante la crisis del decreto de Aman (Est 4:5, 6, 9, 10). Sin el, la comunicacion entre ambos habria sido imposible, pues Ester estaba confinada al palacio y Mardoqueo permanecia afuera. El nombre parece derivar del persa antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93851, 'spa', 'Burlarse, escarnecer', 'Burlarse, mofarse, tratar a alguien con ridículo despectivo (Hifil). La triple acusación de Dalila en Jueces 16:10, 13, 15 es el caso paradigmático: Sansón «se burla» de ella al ocultarle la verdad. Jeremías 9:5 extiende el sentido a una sociedad donde los vecinos se escarnecen mutuamente de forma habitual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93852, 'spa', 'Engañar, embaucar', 'Engañar, embaucar o inducir a creer lo falso (Hifil). Génesis 31:7 lo emplea para el fraude de Labán contra Jacob: «me ha engañado y ha cambiado mi salario diez veces». Éxodo 8:29 advierte a Faraón que no vuelva «a proceder con engaño». Job 13:9 plantea la pregunta demoledora: ¿se puede engañar a Dios «como se engaña a un mortal»?');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93856, 'spa', 'Ser engañado (pasivo)', 'Ser engañado o extraviado (Hofal pasivo). Isaías 44:20 pronuncia el diagnóstico profético de la idolatría: «un corazón engañado lo ha desviado», y el adorador no puede librarse porque no reconoce «la mentira en su mano derecha». Esta única ocurrencia completa el arco semántico del verbo, desde la burla activa hasta el autoengaño resultante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93863, 'spa', 'ganchos del tabernáculo', 'Ganchos o clavijas metálicas fijados a los pilares de la estructura del tabernáculo, utilizados para suspender las cortinas, velos y colgaduras del atrio y del lugar santo. Las 13 apariciones se encuentran en las instrucciones sacerdotales del tabernáculo (Éx 26-27) y en su relato de ejecución (Éx 36-38), fabricados de oro para el velo interior y de plata para los pilares del atrio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93871, 'spa', 'Nombre propio Vasti, que identifica a la reina de Asuero (Jerjes I), destituida ', 'Nombre propio Vasti, que identifica a la reina de Asuero (Jerjes I), destituida tras negarse a acudir al llamado del rey durante su banquete (Est 1:9-19). Su destitución creó la vacante que Ester ocuparía (Est 2:1, 4, 17). Las diez apariciones se limitan a Ester 1-2 y se refieren a esta única persona. Las variantes fonéticas en distintas lenguas — español ''Vasti'', francés ''Vasthi'', alemán ''Waschti'' — adaptan las sibilantes persas a la fonología local conservando la identidad del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93872, 'spa', 'Lobo', 'Un lobo (Canis lupus), el cánido depredador usado a lo largo de las Escrituras como símbolo de ferocidad, violencia y rapacidad. En la bendición de Jacob, Benjamín es llamado un lobo rapaz que despedaza la presa (Gn 49:27). Los textos proféticos emplean lobos como figuras de líderes corruptos y enemigos: los príncipes de Jerusalén son lobos que despedazan la presa (Ez 22:27), sus jueces son lobos nocturnos (Sof 3:3) y los jinetes de Habacuc son más veloces que lobos del atardecer (Hab 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93876, 'spa', 'Zeeb (nombre propio)', 'Zeeb (que significa ''lobo''), príncipe de Madián capturado y ejecutado por los hombres de Efraín en un lugar que después se llamó «el lagar de Zeeb» (Jue 7:25). Aparece junto a Oreb como uno de los dos comandantes madianitas cuya derrota se convirtió en proverbio de liberación divina (Jue 8:3; Sal 83:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93879, 'spa', 'esta (demostrativo)', 'El demostrativo central ''esta'', que señala a una entidad o situación cercana. Omnipresente en fórmulas de pacto (''esta tierra'', Gn 15:7, 18) y en identificaciones narrativas (''esta mujer'', Gn 21:10), funciona como el deíctico femenino primario en todos los géneros literarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93882, 'spa', 'y esto, esto además', 'Unido con la conjunción waw (ו), produce ''y esto'' para introducir elementos adicionales, especificaciones o declaraciones consecuentes. Destaca en listas legales y litúrgicas: ''y esta es la ofrenda'' (Éx 25:3), ''y esta es la ley de...'' (Lv 6:14; 7:1, 11). Función aditiva paralela al francés et ceci.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93883, 'spa', 'en/con/por esto', 'Con la preposición be- (ב), produce ''en esto, con esto, por esto'', marcando instrumento, medio o condición. Fundamental en pruebas y demostraciones narrativas: ''En esto conoceréis'' (Éx 7:17), ''En esto seréis probados'' (Gn 42:15). El alemán dadurch (''por medio de esto'') capta bien la fuerza instrumental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93884, 'spa', 'como esto, así', 'Con la preposición ke- (כ), el pronombre produce ''como esto, así, de esta manera'', expresando modo o comparación. Es común en el discurso referido (''hice así y así'', Jos 7:20) y en descripciones comparativas (Gn 45:23). El francés comme ceci y el alemán wie dies emplean construcciones de manera similares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93893, 'spa', 'a/para esto', 'Con la preposición lamed (ל), produce ''a esto, para esto'', indicando propósito, dirección o causa. Aparece en la memorable exclamación ''esta será llamada mujer'' (Gn 2:23) y en preguntas retóricas sobre el propósito divino (Jer 5:7). El español a esto y el francés à ceci reproducen el sentido direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93901, 'spa', 'más que esto', 'Construcción comparativa poco frecuente con min (מ), que significa ''más que esto'', atestiguada solo en 2 Samuel 6:22, donde David declara que se rebajará aún más que esto. El español más que esto y el francés que ceci captan la fuerza comparativa de este uso único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93915, 'spa', 'Zabad (nombre propio)', 'Nombre propio Zabad (también transliterado Zavad), llevado por múltiples individuos en las tradiciones genealógicas y narrativas. Las traducciones varían: español «Zabad/Zavad», inglés «Zavad», francés y alemán «Zabad». Aparece en listas genealógicas (1 Cr 2:36-37; 7:21), entre los valientes de David (1 Cr 11:41), en el regicidio de Joás y entre quienes se divorciaron de mujeres extranjeras en Esdras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93917, 'spa', 'Zabdi (nombre propio)', 'Zabdi, nombre propio de varios israelitas: (1) abuelo de Acán, de Judá (Jos 7:1, 17, 18), quizá idéntico a Zimri de 1 Cr 2:6; (2) un benjaminita (1 Cr 8:19); (3) oficial a cargo de las bodegas de David (1 Cr 27:27); (4) un levita en tiempos de Nehemías (Neh 11:17). Deriva de una raíz que significa ''regalo'' (cf. árabe zabd) y puede ser hipocorístico de Zabdiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93920, 'spa', 'Zebadías (nombre propio)', 'Nombre propio teofórico que combina una raíz que significa «otorgar, dotar» con el nombre divino YHWH. En español se traduce como «Zebadías», en francés «Zebadia» y en inglés «Zebadiah» o «Zevadyah/Zevadyahu». Aparece solo en Crónicas y Esdras, siempre de individuos diferentes. Entre los portadores más destacados se cuenta el juez principal de Josafat para asuntos reales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93927, 'spa', 'Morada excelsa divina', 'Lugar de habitación exaltado o sublime, usado poéticamente de la morada celestial de Dios o del templo como su contraparte terrenal. Salomón dedica una ''casa de altura'' para el SEÑOR (1 Re 8:13; 2 Cr 6:2), mientras que Isaías 63:15 lo equipara con el cielo mismo. Habacuc 3:11 extiende la imagen a la estación celestial del sol y la luna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93928, 'spa', 'Zabulón (persona, tribu, territorio) — El nombre propio Zabulón (זְבוּלֻן), que ', 'Zabulón (persona, tribu, territorio) — El nombre propio Zabulón (זְבוּלֻן), que designa al sexto hijo de Jacob y Lea (Gn 30:20; 35:23), la tribu israelita descendiente de él (Nm 1:30-31; Jue 4:6, 10; 5:14, 18) y el territorio tribal en la baja Galilea (Jos 19:10-16; Is 8:23). La bendición de Jacob asocia a Zabulón con el mar (Gn 49:13), y el cántico de Débora celebra el valor de la tribu en el campo de batalla (Jue 5:18). Las 45 ocurrencias abarcan por metonimia persona, tribu y tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93941, 'spa', 'Gentilicio tribal', 'Funciona como gentilicio tribal en contextos de censo (Nm 26:27) y narrativa (Jue 12:11-12). El término identifica a individuos o grupos por su descendencia de Zabulón, décimo hijo de Jacob. Se emplea tanto en singular para designar a una persona como en plural para referirse al clan completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93942, 'spa', 'ofrecer sacrificio (Qal cultual)', 'El acto cultual de ofrecer sacrificio al Señor o a dioses falsos. Las traducciones multilingües emplean de manera consistente vocabulario sacrificial dedicado (hindi बलि, árabe ذَبَحَ, suajili kutoa dhabihu), distinguiendo este rito religioso de la mera matanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93955, 'spa', 'sacrificar habitualmente (Piel)', 'El tronco Piel intensivo marca una práctica sacrificial habitual o reiterada, a menudo en contextos de idolatría persistente o actividad cultual sostenida. Esta forma intensifica el aspecto iterativo del acto sacrificial, distinguiéndolo de una ofrenda puntual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (93958, 'spa', 'degollar, matar animal (Qal)', 'El acto físico de matar un animal, separado del rito religioso. Las glosas se desplazan hacia la terminología de la matanza (español matarás/degolló) en lugar del lenguaje sacrificial, indicando la distinción semántica entre el sacrificio cultual y la simple matanza para consumo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94028, 'spa', 'sacrificio (ofrenda animal)', 'El sentido primario: un sacrificio animal ofrecido en el culto, ya sea al Señor o a otros dioses. Abarca toda la gama de formas gramaticales: singular, plural, cadenas constructas (''sacrificio de ofrendas de paz''), frases preposicionales (''con sacrificio'') y construcciones posesivas. Cubre ofrendas de comunión (Lv 3:1), ofrendas votivas (Lv 7:16) y el sacrificio en general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94073, 'spa', 'sacrificios de (contrastivo)', 'En Proverbios 17:1 (''Mejor es un bocado seco con paz, que una casa llena de sacrificios con discordia''), la forma constructa ''sacrificios de'' porta un matiz contrastivo, casi irónico: la abundancia de banquetes sacrificiales arruinada por el conflicto. El sentido sigue siendo ''sacrificio'', pero el contexto proverbial le confiere una valencia negativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94076, 'spa', 'altares/sacrificios (metonimia)', 'En Oseas 4:19, la forma aparece en un contexto de adoración idolátrica vergonzosa (''se avergonzarán de sus altares/sacrificios''). Aquí se produce una extensión metonímica donde los sacrificios y los lugares de culto se funden, evocando no solo el acto sacrificial sino todo el aparato cultual ilícito asociado con él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94078, 'spa', 'Nombre propio Zébaj, que designa al rey madianita que, junto con Zalmuna, fue pe', 'Nombre propio Zébaj, que designa al rey madianita que, junto con Zalmuna, fue perseguido y ejecutado por Gedeón tras la liberación de Israel de la opresión madianita (Jue 8:5-21). Su nombre se volvió proverbial como ejemplo de juicio divino contra los enemigos de Israel (Sal 83:11). Las variantes conjuntivas y preposicionales (''y Zébaj'', ''como Zébaj'') son sintácticas, no semánticas. Todas las lenguas preservan la transliteración del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94085, 'spa', 'Zebul (nombre propio)', 'Zebul, oficial (gobernador o prefecto) de Siquem al servicio de Abimelec. Sus seis ocurrencias se concentran en Jueces 9:28-41, donde actúa como agente leal de Abimelec: informa de la conspiración de Gaal (v. 30), se mofa de Gaal al acercarse las fuerzas enemigas (vv. 36, 38) y permanece en la ciudad tras el conflicto (v. 41). El nombre puede vincularse etimológicamente a zebul (''morada exaltada'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94089, 'spa', 'insolente, arrogante', 'Persona caracterizada por una presunción insolente contra Dios, usado sustantivamente como término casi técnico para el rebelde impío. Predomina en el Salmo 119 (vv. 21, 51, 69, 78, 85, 122), donde los ''zedim'' son quienes se apartan de los mandamientos y colman de escarnio al salmista. También aparece en juicio profético (Is 13:11; Mal 3:15, 19) y en caracterización proverbial (Pr 21:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94095, 'spa', 'Insolencia, orgullo presuntuoso o autoafirmación arrogante', 'Insolencia, orgullo presuntuoso o autoafirmación arrogante: una disposición de desafío altivo contra la autoridad legítima. Abarca los registros legal, sapiencial y profético: desafío presuntuoso de la autoridad sacerdotal o judicial (Dt 17:12), pronunciamiento profético falso (Dt 18:22), arrogancia personal reprendida (1 S 17:28), advertencias sapienciales de que la soberbia engendra contienda y deshonra (Pr 11:2; 13:10; 21:24), y la personificación profética de Babilonia como ''la soberbia'' que Dios abatirá (Jer 50:31-32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94103, 'spa', 'este, esto (demostrativo)', 'El pronombre demostrativo nuclear que significa ''este'', ''esto'', ''esta cosa'': con diferencia el sentido dominante, con aproximadamente 1.059 de 1.178 apariciones. Señala personas, objetos, lugares, tiempos y situaciones en proximidad inmediata o en el contexto discursivo: ''este día'' (Gn 7:11), ''este hombre'' (Gn 19:21), ''este lugar'' (Gn 20:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94106, 'spa', 'de aquí, de este lado', 'Con la preposición מִן: מִזֶּה, ''de aquí'', ''de este lado'' — aproximadamente 90 apariciones. Este sentido es especialmente prominente en el par direccional מִזֶּה...וּמִזֶּה (''de un lado y del otro''), usado para describir posiciones espaciales de flanqueo (Éx 17:12; Jos 8:22). En Gn 37:17, a José le dicen ''se fueron de aquí''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94108, 'spa', 'en esto, aquí (locativo)', 'Con la preposición בְּ o לְ: בָּזֶה, ''en esto'', ''aquí'', ''en este lugar'', ''por este medio'' — aproximadamente 19 apariciones. En Gn 38:21-22 Judá pregunta por la prostituta cultual ''en este lugar''; en Gn 48:9 José dice ''Dios me los ha dado aquí''; en Éx 24:14 Moisés dice ''esperad aquí''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94118, 'spa', 'como esto, así (comparativo)', 'Con la preposición כְּ: כָּזֶה, ''como esto'', ''así'', ''de esta manera'' — aproximadamente 10 apariciones. El modismo כָּזֶה וְכָזֶה (''tal y cual'', lit. ''como esto y como aquello'') aparece en 2 S 11:25. En Gn 41:38 el Faraón pregunta ''¿Acaso hallaremos otro como este?'' — uso que combina deixis con valoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94140, 'spa', 'Pronombre demostrativo femenino que significa ''esta'', señalando un referente, si', 'Pronombre demostrativo femenino que significa ''esta'', señalando un referente, situación o experiencia específica en el contexto inmediato. Funcionalmente idéntico a zōʾt pero preferido en el uso tardío o dialectal, especialmente en Eclesiastés, donde es el único demostrativo femenino. Pasajes clave incluyen Ecl 2:2, 24; 5:15-18 y 2 R 6:19, donde Eliseo redirige a los soldados arameos: ''este no es el camino''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94141, 'spa', 'Combinado con la preposición ke- para formar la expresión adverbial kāzōh que si', 'Combinado con la preposición ke- para formar la expresión adverbial kāzōh que significa ''así, de esta manera''. Generalmente emparejado con el masculino kāzeh en la fórmula kāzōh wekāzeh (''así y así''), usada para resumir discurso referido sin citar textualmente. Jue 18:4 (''así y así me trató Micaía'') y 2 S 11:25 (''así es la espada'') ejemplifican esta función de resumen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94143, 'spa', 'oro (el metal)', 'El metal precioso oro en todos sus roles bíblicos: como mineral extraído de la tierra (Gn 2:11-12; Job 28:1), como material refinado para el mobiliario sagrado como el recubrimiento del Arca y el candelabro (Éx 25:11, 31), como medida de riqueza y esplendor real (1 R 10:11), y como patrón figurado de pureza y valor (Pr 17:3; Job 23:10). Cognado en toda la familia semítica: árabe ذهب, arameo דהב.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94171, 'spa', 'Recibir advertencia, ser amonestado', 'Recibir advertencia, ser amonestado: El sentido reflexivo-pasivo del Nifal: recibir advertencia, ser amonestado o prestar atención a una amonestación -- el lado de la respuesta del acto de advertir. Los oráculos del atalaya en Ezequiel hacen de la respuesta del oyente el eje entre la vida y la muerte: ''si el impío se deja advertir, librará su alma'' (Ez 33:4-5, 3:21). La tradición sapiencial extiende esto al consejo reflexivo: el salmista descubre que por los juicios de Dios ''tu siervo es advertido'' (Sal 19:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94172, 'spa', 'Advertir, amonestar', 'Advertir, amonestar: El sentido activo del Hifil: advertir, amonestar o dar aviso preventivo a otra persona. Quien advierte actúa como intermediario que transmite el mensaje de Dios o información práctica. La comisión del atalaya en Ezequiel es el caso paradigmático: Dios dice ''te he puesto por atalaya -- les advertirás'' (Ez 3:17, 33:7), y la responsabilidad moral del profeta depende de si entrega la advertencia (Ez 3:18-19). Moisés también recibe la orden de ''advertir'' al pueblo sobre los estatutos de Dios (Éx 18:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94189, 'spa', 'este, que, quien', 'Pronombre arcaico e indeclinable que funciona tanto demostrativamente (''este'') como relativamente (''que, quien, a quien'') en el hebreo poético y litúrgico. Como demostrativo: Hab 1:11 ''esta su fuerza'', Sal 62:11 ''estas dos cosas''. Como relativo: Éx 15:13 ''el pueblo que redimiste'', Is 42:24 ''contra quien pecamos'', Sal 9:15 ''la red que escondieron''. La evidencia interlingüística refleja esta dualidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94193, 'spa', 'fluir, manar — Fluir o brotar, especialmente de líquidos en abundancia', 'fluir, manar — Fluir o brotar, especialmente de líquidos en abundancia. Cubre tanto la imagen poética del agua que brota de la roca (Sal 78:20; Is 48:21) como la célebre fórmula ''tierra que fluye leche y miel'' (Éx 3:8, 17; Dt 6:3 y passim). El participio זָבַת en la fórmula de ''leche y miel'' prácticamente se ha lexicalizado como epíteto de la tierra prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94194, 'spa', 'persona con flujo corporal — Participio sustantivado (זָב) que designa a una per', 'persona con flujo corporal — Participio sustantivado (זָב) que designa a una persona que padece una emisión corporal anormal. Es casi un término técnico-legal en Levítico 15, donde define una categoría de impureza ritual. El זָב está sujeto a regulaciones detalladas de purificación (Lv 15:2-15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94198, 'spa', 'flujo, emisión (nominal) — Uso nominal referido al flujo mismo y no a la persona', 'flujo, emisión (nominal) — Uso nominal referido al flujo mismo y no a la persona que lo padece, atestiguado en Levítico 15:19 con sufijo posesivo femenino (זוֹבָהּ, ''su flujo''). Este sentido se estrecha del sujeto que fluye a la sustancia que fluye, particularmente la emisión menstrual o genital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94205, 'spa', 'consumirse, languidecer — Extensión figurada que significa consumirse o languide', 'consumirse, languidecer — Extensión figurada que significa consumirse o languidecer, como de aquellos cuya vida se va escurriendo como un líquido. Atestiguado en Lamentaciones 4:9, donde los traspasados por la espada corren mejor suerte que quienes se consumen de hambre: la vida que se drena lentamente en vez de derramarse. El cognado árabe ذَابَ (''derretirse, disolverse'') respalda esta extensión metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94206, 'spa', 'flujo corporal', 'Descarga o flujo genital que provoca impureza ritual, usado exclusivamente dentro del código de pureza sacerdotal de Levítico 15. Abarca tanto el flujo menstrual normal de la mujer (Lv 15:19) como las emisiones patológicas en hombres y mujeres (Lv 15:2-15, 25-30). La restricción del término a un solo capítulo legislativo destaca su función como categoría cúltico-médica precisa, no como palabra general para funciones corporales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94213, 'spa', 'Actuar con presunción, arrogancia o desafío voluntario, especialmente contra Dio', 'Actuar con presunción, arrogancia o desafío voluntario, especialmente contra Dios o la autoridad legítima. Abarca el sentido legal-pactual presente en la Torá y los Profetas: la presunción de Egipto contra Israel (Éx 18:11), el homicida premeditado que ''actúa con soberbia'' (Éx 21:14), la desobediencia descarada de Israel en Hormá (Dt 1:43), el falso profeta que habla sin comisión divina (Dt 18:20) y la rebelión crónica de Israel contra los mandamientos de Dios (Neh 9:10, 16, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94218, 'spa', 'Hervir, cocer a fuego', 'Hervir, cocer a fuego: raíz homónima atestiguada solo en Gn 25:29, donde Jacob ''coció'' (wayyazed) un guiso de lentejas. La evidencia multilingüe confirma una ruptura semántica clara: el español usa ''coció'', el francés ''bouilli'' y el alemán ''kochte'', ninguno de los cuales conserva rastro del significado de arrogancia. Se trata mejor como una raíz distinta (zid/zud II).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94226, 'spa', 'Excepto, fuera de — Preposición que significa ''excepto, aparte de, fuera de'', us', 'Excepto, fuera de — Preposición que significa ''excepto, aparte de, fuera de'', usada para indicar exclusión o única excepción. Aparece en contextos narrativo-legales para singularizar individuos: Caleb como único librado del decreto del desierto (Deut 1:36), la única espada disponible en Nob (1 Sam 21:9). Notablemente, porta fuerza monoteísta en declaraciones proféticas: ''no hay Dios fuera de mí'' (Os 13:4; Is 45:5, 21), y en la oración de David reconociendo la incomparabilidad de YHWH (2 Sam 7:22 = 1 Cr 17:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94236, 'spa', 'Temblar y sacudir', 'Describe el temblor provocado por el miedo (Est 5:9), la agitación de los miembros en la vejez (Ecl 12:3) y la sacudida violenta del juicio divino (Hab 2:7). El campo semántico abarca los dominios emocional, fisiológico y de violencia, oscilando entre el temblor involuntario y la agitación forzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94237, 'spa', 'Temblar de pavor', 'Temblar o estremecerse de miedo ante una autoridad soberana. Usado en las secciones arameas de Daniel como participio que describe la reaccion de espanto de pueblos y naciones. Ante Nabucodonosor, todos temblaban por su poder de vida y muerte (Dan 5:19); luego ese mismo lenguaje se aplica al Dios de Daniel, ante quien toda la tierra debe estremecerse (Dan 6:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94238, 'spa', 'Temblor, horror, espanto', 'Objeto de temblor, horror o terror: algo que provoca estremecimiento en otros. Se emplea casi exclusivamente en fórmulas de maldición pactual donde Dios declara que una nación o ciudad será convertida en objeto de espanto para los reinos circundantes. Deuteronomio 28:25 inaugura la fórmula, y Jeremías la intensifica en cuatro pasajes (15:4; 24:9; 29:18; 34:17), frecuentemente junto a términos como oprobio y maldición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94243, 'spa', 'Extraño, forastero (persona)', 'Extraño, forastero (persona): el uso participial dominante que funciona como sustantivo, designando a un extraño, forastero o intruso no autorizado. En contextos levíticos (Lev 22:10, 12, 13; Éx 29:33), se refiere a cualquier persona ajena al hogar sacerdotal a quien se le prohíbe participar de las cosas sagradas. La evidencia multilingüe es notablemente uniforme, convergiendo en el significado central de exclusión social y ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94248, 'spa', 'Extraño, ajeno (cosas/dioses)', 'Extraño, ajeno (cosas/dioses): aplicado atributivamente a referentes no personales — fuego extraño (Lev 10:1; Nm 3:4, 26:61), incienso extraño (Éx 30:9), dioses ajenos y cosas foráneas. La lógica subyacente es la misma que en la acepción 1 (lo que no pertenece), pero el referente cambia de personas a objetos, ofrendas y deidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94249, 'spa', 'Mujer extraña, adúltera', 'Mujer extraña, adúltera: el uso especializado de Proverbios para la זָרָה, la ''mujer extraña'' o adúltera cuyos labios destilan miel pero cuyo fin es amargo como el ajenjo (Pr 5:3-4). Aparece en Pr 2:16, 5:3, 5:20, 7:5 y 22:14, distinguiéndose por su contexto literario constante en la poesía sapiencial y su connotación moral-sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94255, 'spa', 'Ser extrañado, apartarse (Qal)', 'Ser extrañado, apartarse (Qal): el verbo finito Qal que significa volverse extraño, alienarse o apartarse. En Sal 58:3 los impíos ''se desvían desde el vientre'', y en Job 19:13 los conocidos de Job se han extrañado completamente de él. Sal 78:30 describe a Israel apartándose antes de saciar su deseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94256, 'spa', 'Ser extrañado, retroceder (Nifal)', 'Ser extrañado, retroceder (Nifal): la forma Nifal (pasiva/reflexiva) que expresa el extrañamiento como algo sufrido o autodirigido — ser alienado, retroceder, apartarse. En Is 1:4 Israel ha ''retrocedido'' (se ha vuelto del SEÑOR), y en Ez 14:5 la casa de Israel ''se ha apartado de mí por sus ídolos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94273, 'spa', 'Exprimir y aplastar', 'El verbo aparece en contextos de exprimir líquido (Jue 6:38), aplastar bajo los pies (Job 39:15) y no tratar una herida por falta de presión (Is 1:6, voz pasiva). El núcleo semántico consiste en aplicar fuerza para extraer, comprimir o destruir materia sólida o semisólida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94281, 'spa', 'Brillo, esplendor del semblante', 'Brillo o esplendor, especialmente del semblante o apariencia exterior de una persona. En Daniel 2:31 describe la radiancia extraordinaria de la gran estatua del sueño de Nabucodonosor. En Daniel 4:36 marca el retorno de la dignidad real tras siete años de humillación. En la narrativa de Belsasar (Dan 5:6, 9, 10) describe el cambio en el brillo del rostro del rey, es decir, la alteración de su semblante por el terror.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94293, 'spa', 'El nombre propio Zif, empleado para', 'El nombre propio Zif, empleado para: (1) una ciudad en la serranía de Judá cerca de Hebrón (Jos 15:55; 2 Cr 11:8) y su desierto circundante donde David se refugió de Saúl (1 Sam 23:14-15, 24; 26:2); (2) una ciudad en el Néguev de Judá (Jos 15:24); y (3) un individuo judahíta, hijo de Jehallelel (1 Cr 4:16). La forma direccional ziphah (''hacia Zif,'' 1 Sam 23:24) y el constructo midbar-ziph (''desierto de Zif'') confirman su uso toponímico predominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94297, 'spa', 'Habitantes de Zif', 'Gentilicio que identifica a los residentes de Zif en la región montañosa de Judá. Su aparición bíblica más notable se vincula a la doble delación de David ante el rey Saúl, un acto de traición inmortalizado en el encabezado del Salmo 54.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94298, 'spa', 'Proyectil ígneo', 'Designa proyectiles de fuego o chispas en tres contextos: misiles mortales (Prov 26:18) y tizones encendidos como juicio (Isa 50:11, dos veces). Las glosas multilingües (chispas, firebrands, זִקִּים) subrayan la cualidad saltarina y voladora del fuego. La palabra evoca peligro, imprevisibilidad y la violencia de la llama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94299, 'spa', 'Grillos o cadenas', 'Grillos o cadenas para sujetar cautivos, en sentido literal y figurado. Literalmente, las cadenas atan a prisioneros de guerra: los nobles de Ninive en Nah 3:10, pueblos subyugados en Isa 45:14 y reyes en Sal 149:8 (en paralelo con ''grilletes de hierro''). Figuradamente, Job 36:8 describe la afliccion como estar ''atado con grillos'', representando la disciplina divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94300, 'spa', 'olivo (árbol) — El olivo cultivado (Olea europaea) en huertos, campos y lenguaje', 'olivo (árbol) — El olivo cultivado (Olea europaea) en huertos, campos y lenguaje figurado. Génesis 8:11 introduce la rama de olivo; Deuteronomio 8:8 lo incluye entre las siete especies de la tierra prometida; el Salmo 52:8 compara al justo con un olivo frondoso en la casa de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94306, 'spa', 'los Olivos (Monte de los Olivos) — El topónimo ''Monte de los Olivos'' (הַר הַזֵּי', 'los Olivos (Monte de los Olivos) — El topónimo ''Monte de los Olivos'' (הַר הַזֵּיתִים), donde el plural funciona como parte de un nombre propio para la colina al este de Jerusalén. David la sube llorando (2 S 15:30); Zacarías 14:4 vislumbra que se partirá a la venida del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94312, 'spa', 'aceituna (fruto) — La aceituna como fruto o producto agrícola, distinguida en es', 'aceituna (fruto) — La aceituna como fruto o producto agrícola, distinguida en español del árbol. Miqueas 6:15 habla de pisar aceitunas pero no ungirse con aceite, un oráculo de juicio donde la cosecha fracasa en la etapa del fruto. El español separa ''aceituna'' (el fruto comestible) de ''olivo'' (el árbol), revelando una distinción semántica que el hebreo deja implícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94324, 'spa', 'Adjetivo que significa ''puro, limpio, claro'', denotando ausencia de contaminació', 'Adjetivo que significa ''puro, limpio, claro'', denotando ausencia de contaminación o impureza tanto en el ámbito físico como moral. En lo físico, califica el aceite de oliva para el candelabro del tabernáculo (Éx 27:20; Lv 24:2) y el incienso para los panes de la proposición (Éx 30:34; Lv 24:7). En lo moral, describe la integridad personal o la aspiración a ella (Job 8:6; 11:4; 16:17; 25:5; Pr 16:2; 20:11; 21:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94327, 'spa', 'Ser puro, limpio', 'Ser puro o limpio en sentido moral (Qal estativo): describe la condición de ser íntegro o inocente ante Dios. Los amigos de Job plantean la pregunta retórica: ''¿Qué es el hombre para que sea puro?'' (Job 15:14; 25:4). El salmista afirma el derecho de Dios a juzgar: ''Eres justo cuando hablas'' (Sal 51:4). El paralelo con tsadaq (''ser justo'') confirma el campo semántico de rectitud moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94328, 'spa', 'Purificar, limpiar', 'Hacer puro o mantener limpio (Piel factitivo): el esfuerzo activo de purificar o conservar la pureza. El Salmo 119:9 pregunta cómo un joven puede mantener limpio su camino; el Salmo 73:13 lamenta ''en vano he purificado mi corazón''; Proverbios 20:9 plantea el desafío universal: ''¿Quién puede decir: he limpiado mi corazón?'' Refleja un proceso sostenido y voluntario de purificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94332, 'spa', 'Purificarse a sí mismo', 'Purificarse a uno mismo (Hitpael reflexivo): mandato autodirigido de someterse a limpieza moral o ritual. Solo Isaías 1:16 lleva esta conjugación: ''¡Lavaos, purificaos!'' El imperativo reflexivo en español ''purificaos'' refleja con precisión la fuerza reflexiva del hebreo. La progresión del Qal al Piel y al Hitpael traza un arco completo de pureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94337, 'spa', 'Varones como colectivo', 'Varones como categoria colectiva, siempre con sufijo posesivo. En las leyes festivas (Ex 23:17; 34:23; Dt 16:16), ''todos tus varones'' designa a cada israelita obligado a peregrinar; el termino es cultual y corporativo. En la ley de guerra (Dt 20:13), ''todos sus varones'' se refiere a los hombres en edad militar de una ciudad conquistada. Sinonimo de זָכָר pero restringido a formas sufijadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94338, 'spa', 'El nombre propio hebreo Zacur/Zakur (de zakhar, ''recordar''), portado por múltipl', 'El nombre propio hebreo Zacur/Zakur (de zakhar, ''recordar''), portado por múltiples individuos: un espía rubenita (Nm 13:4), un descendiente simeonita (1 Cr 4:26), músicos y servidores levíticos del templo (1 Cr 24:27; 25:2, 10; Neh 10:12; 12:35), un reconstructor del muro bajo Nehemías (Neh 3:2) y un compañero de Esdras (Esd 8:14). A pesar de la variedad de portadores, el nombre constituye una unidad léxica única.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94340, 'spa', 'Nombre propio', 'Nombre propio que aparece en tres listas genealógicas o censales del período postexílico (Esd 2:9; Neh 3:20; 7:14). Las glosas en distintos idiomas transliteran el nombre uniformemente, tratándolo como un identificador personal fijo. Cualquier conexión etimológica con Zacarías es un dato de fondo, no semánticamente activo en estos textos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94341, 'spa', 'Brillante o radiante', 'Ser brillante o radiante, describiendo esplendor fisico. En Lam 4:7 los nobles de Jerusalen ''eran mas puros que la nieve, mas blancos que la leche'', usando זָכַךְ en paralelo con צָחַח para pintar una imagen de salud y belleza deslumbrantes antes de que el asedio los destruyera. El sentido raiz es pureza luminosa, visible e impactante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94342, 'spa', 'Qal: recordar, acordarse', 'Sentido activo básico del Qal: traer a la mente a alguien o algo, evocar o pensar de nuevo. Abarca sucesos pasados, personas, promesas pactuales y obras divinas. Cuando Dios es el sujeto (Gn 8:1; Éx 2:24), ''recordar'' implica acción salvífica, no mera cognición. El coreano 기억하다, el árabe ذَكَرَ y el español ''recordar'' convergen en este significado nuclear a lo largo de 173 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94348, 'spa', 'Nifal: ser recordado', 'Pasivo del Nifal: ser recordado, venir a la memoria. Se aplica a personas, nombres o cosas que son —o dejarán de ser— evocadas (Job 24:20; Est 9:28). El español lo traduce como ''ser recordado'' y el alemán como ''gedacht werden'', subrayando la recepción pasiva frente al recuerdo activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94355, 'spa', 'Hifil ptcp.: el cronista', 'Participio Hifil usado como título cortesano: הַמַּזְכִּיר, ''el cronista'' o ''el registrador''. Este funcionario aparece en las listas de administradores de David y Salomón (2 S 8:16; 1 R 4:3) y también bajo Ezequías (2 R 18:18, 37). El español ''cronista'', el francés ''archiviste'' y el coreano 사관 apuntan a un cargo institucional diferenciado: el custodio de la memoria estatal y los anuncios públicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94365, 'spa', 'Hifil: mencionar, invocar', 'Causativo del Hifil en su vertiente declarativa: hacer mención, invocar por nombre, proclamar públicamente. Se distingue del sentido 3 por el énfasis en la expresión verbal más que en el recuerdo mental. Se prohíbe a Israel ''mencionar'' (לֹא תַזְכִּירוּ) los nombres de otros dioses (Éx 23:13; Jos 23:7), y el salmista declara: ''nosotros invocaremos el nombre de YHWH'' (Sal 20:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94368, 'spa', 'Hifil: hacer recordar', 'Causativo del Hifil en su vertiente memorial: hacer que alguien recuerde, traer a la memoria, recordar. La ofrenda de celos es llamada מִנְחַת מַזְכֶּרֶת que ''hace recordar la iniquidad'' (Nm 5:15), y Absalón erige una estela para que su nombre sea recordado (2 S 18:18). El francés ''faire souvenir'' y el español ''hacer recordar'' captan esta fuerza causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94471, 'spa', 'Memoria, recuerdo', 'Memoria, recuerdo: Memoria, recuerdo o evocación -- el acto o el contenido de recordar a alguien o algo. Este sentido dominante (18 apariciones) abarca contextos tanto de preservación como de destrucción de la memoria. Dios ordena borrar la ''memoria'' de Amalec de debajo del cielo (Éx 17:14, Dt 25:19), pero el justo goza de ''eterna memoria'' (Sal 112:6). Job 18:17 empareja זֵכֶר con שֵׁם (nombre), mostrando que la memoria y la identidad están íntimamente ligadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94475, 'spa', 'Renombre, fama', 'Renombre, fama: Renombre, fama o reputación celebrada -- la dimensión pública de ser recordado. Este sentido poco frecuente (1 aparición) surge en Os 14:7, donde el renombre (זִכְרוֹ) del Efraín restaurado será como la fragancia del Líbano. Se trasciende la memoria privada para llegar a la aclamación pública, marcando un punto semántico distinto en el espectro del recuerdo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94476, 'spa', 'Memorial, conmemoración', 'Memorial, conmemoración: Un memorial, signo conmemorativo o recordatorio establecido -- algo intencionalmente creado para preservar la memoria a través de las generaciones. Dios dice a Moisés ''este es mi memorial (זִכְרִי) para siempre'' (Éx 3:15), investiendo el nombre divino con fuerza conmemorativa. El Salmo 111:4 declara que Dios ''ha hecho memorables sus maravillas'', y Os 12:5 lo usa del nombre de pacto de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94489, 'spa', 'Varón (ser humano)', 'Varón (ser humano): un ser humano de sexo masculino — hombre o niño — usado en contraste con hembra (נְקֵבָה) al describir el género en los relatos de la creación (Gn 1:27, ''varón y hembra los creó''), registros de censo, códigos legales y genealogías. Las traducciones en español usan consistentemente ''varón'' para el sentido humano, confirmando la referencia antropológica primaria en 79 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94495, 'spa', 'Macho (animal)', 'Macho (animal): un animal macho, específicamente en la legislación sacrificial y ritual donde se requiere un macho sin defecto del rebaño o la manada como ofrenda a YHWH. El español cambia a ''el macho'' con el artículo definido marcando la especificación ritual. Atestiguado en Éx 13:12 (primogénitos machos consagrados) y Dt 15:19 (primogénito macho de la manada).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94501, 'spa', 'Signo memorial o emblema', 'Signo memorial o emblema: Un objeto conmemorativo concreto, ofrenda o signo destinado a servir como recordatorio permanente. Las doce piedras en el Jordán son ''un memorial'' (Jos 4:7), las piedras grabadas de los hombros del efod llevan los nombres de las tribus ''por memorial'' (Éx 28:12), y la ofrenda de cereal se llama אַזְכָּרָה, una ''porción memorial'' (Nm 5:15). Este sentido enfatiza lo tangible e institucional del acto de recordar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94502, 'spa', 'Recuerdo o memoria', 'Recuerdo o memoria: El estado abstracto de ser recordado o el acto mismo de la evocación. Eclesiastés 1:11 lamenta que ''no hay memoria de las cosas anteriores'', y Nehemías 2:20 afirma que ciertas personas no tienen ''porción ni derecho ni memoria'' en Jerusalén. Aquí el enfoque está en la memoria como facultad o estado, no como objeto físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94506, 'spa', 'Registros escritos o crónicas', 'Registros escritos o crónicas: Registros escritos formales o crónicas preservadas para la posteridad. Ester 6:1 describe al rey ordenando que se leyera ''el libro de las memorias'' (los anales reales) -- un acto que invierte de forma decisiva la trama de Amán. Es la memoria institucionalizada en texto, una extensión burocrática del impulso conmemorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94507, 'spa', 'Dichos memorables o máximas', 'Dichos memorables o máximas: Dichos memorables, máximas o sentencias proverbiales. Job 13:12 declara ''vuestros memoriales son proverbios de ceniza'' -- un rechazo devastador de la sabiduría tradicional de sus amigos como lugares comunes sin valor. Este uso poco frecuente extiende el sustantivo de las cosas recordadas a las cosas que merecen ser recordadas -- la sabiduría oral transmitida como herencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94514, 'spa', 'El nombre propio Zicri (zikhri), portado por al menos nueve individuos distintos', 'El nombre propio Zicri (zikhri), portado por al menos nueve individuos distintos en Éxodo, Crónicas y Nehemías, incluyendo levitas, benjaminitas y un guerrero efrateo. El nombre probablemente deriva de zakhar (''recordar''), sugiriendo ''mi recuerdo'' o ''Yah ha recordado''. A pesar de sus múltiples referentes, el nombre funciona como una sola unidad léxica que se preserva uniformemente por transliteración en las lenguas receptoras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94516, 'spa', 'Zacarías (nombre propio) — El nombre propio masculino Zekharyahu/Zekharyah (''Yah', 'Zacarías (nombre propio) — El nombre propio masculino Zekharyahu/Zekharyah (''Yah ha recordado''), compartido por numerosos individuos a lo largo de los períodos monárquico y postexílico. Entre los portadores principales se cuentan el breve rey israelita asesinado por Salum (2 R 15:8-11), el abuelo materno de Ezequías (2 R 18:2), el testigo de Isaías (Is 8:2), varios levitas y músicos (1 Cr 15:18, 20; 26:2, 11) y funcionarios bajo Josafat. La popularidad del nombre atestigua su resonancia teológica: Dios recuerda a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94527, 'spa', 'Glotón, despreciable', 'Ser glotón, derrochador o persona pródiga con la comida y la bebida. Se usa como participio sustantivado (''un glotón''), emparejado sistemáticamente con סֹבֵא (''borracho'') en Deuteronomio 21:20 y Proverbios 23:20-21 y 28:7. El verbo implica consumo desenfrenado y un estilo de vida disoluto. Una segunda vertiente extiende el significado a ser vil o insignificante, como en Jeremías 15:19 y Lamentaciones 1:11.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94533, 'spa', 'Calor destructor', 'Designa calor destructivo en tres formas: ardor febril por hambruna (Lam 5:10), viento abrasador de juicio (Sal 11:6) e indignación ardiente de carácter emocional (Sal 119:53). Las glosas multilingües (ardor, abrasador, horreur) reflejan tanto el registro físico como el afectivo. El núcleo semántico es una intensidad abrumadora y consumidora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94534, 'spa', 'Zilpá (nombre propio)', 'Nombre propio de la sierva de Lea que se convirtió en una de las esposas de Jacob. Zilpá aparece en las narrativas patriarcales como parte del complejo arreglo familiar mediante el cual se originaron las doce tribus. Las traducciones multilingües transliteran consistentemente el nombre (español Zilpá, francés Zilpa, alemán Silpa), reflejando su condición de nombre personal reconocido en toda la tradición bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94535, 'spa', 'Maldad, intención perversa', 'Maldad, intención perversa: Maldad general o intención perversa sin una dimensión específicamente sexual. En el Salmo 26:10 se asocia con el soborno (שֹׁחַד), el Salmo 119:150 describe a los perseguidores de la maldad, y Proverbios 10:23 y 21:27 lo aplican al deleite del necio en el mal y al sacrificio del impío. El vocabulario moral se amplía más allá de lo sexual hacia la vileza en general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94536, 'spa', 'Lascivia, depravación sexual', 'Lascivia, depravación sexual: Inmoralidad sexual, lascivia o depravación -- el uso más frecuente y distintivo. Ezequiel emplea זִמָּה repetidamente para referirse a la prostitución y las abominaciones de Jerusalén (Ez 16:27, 43, 58; 22:9; 23:21-49), Levítico lo aplica al incesto y la prostitución cultual (Lv 18:17; 19:29; 20:14), y Job califica el adulterio como una זִמָּה (Job 31:11). La evidencia interlingüística es contundente: las traducciones alcanzan consistentemente vocabulario específicamente sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94543, 'spa', 'Plan, maquinación', 'Plan, maquinación: Un plan, maquinación o propósito deliberado -- la base etimológica de la palabra. Job 17:11 lamenta que ''mis planes (זִמֹּתַי) se han frustrado'', usando el término sin connotación negativa. Proverbios 24:9 llama pecado al plan de la necedad, e Isaías 32:7 describe las maquinaciones del villano. Este sentido preserva la noción de deliberación y cálculo que subyace a los demás usos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94555, 'spa', 'Nombre propio levítico', 'Nombre propio que identifica a levitas en tres contextos genealógicos (1 Cr 6:20, 42; 2 Cr 29:12). Las glosas en distintas lenguas transliteran el nombre uniformemente, tratándolo como identificador fijo. Aunque la raíz sugiere «infamia», el nombre no porta aquí fuerza peyorativa alguna, ilustrando la brecha entre etimología y uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94556, 'spa', 'Rama o sarmiento', 'Rama, sarmiento o brote, especialmente de la vid, usado tanto literal como figuradamente. Literalmente en Números 13:23, donde el sarmiento de Escol muestra la fertilidad de la tierra, y en Ezequiel 15:2 de la madera de vid. Figuradamente en Isaías 17:10 para plantíos cultuales idolátricos y en Nahúm 2:2 para el pueblo de Israel. El uso enigmático de Ezequiel 8:17 podría referirse a una rama ritual empleada en adoración pagana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94558, 'spa', 'Cántico, salmo', 'Cántico, salmo o composición musical, particularmente de alabanza o adoración. Se aplica a los salmos de David (2 Sam 23:1), a cánticos nocturnos dados por Dios (Job 35:10), a gritos de adoración (Sal 95:2), a los estatutos atesorados como canciones (Sal 119:54), e incluso al cántico triunfal de opresores despiadados (Isa 25:5). Abarca todo el rango de música vocal compuesta en contexto bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94565, 'spa', 'proponerse o planear', 'Proponerse, determinar o resolver un curso de acción, usado para la planificación deliberada tanto de Dios como de los humanos sin connotación negativa inherente. El español ''ha determinado'' y el inglés ''I have purposed'' convergen en la resolución firme. Central en pasajes de decreto divino: Dios lo determina y no se arrepiente (Jer 4:28; Lm 2:17), y en Babel el pueblo propone lo que hará (Gn 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94569, 'spa', 'maquinar o tramar', 'Maquinar, tramar o urdir el mal contra alguien, con connotación claramente maliciosa. El español ''maquinar/tramaron'' y el alemán ''plant Böses'' (''planea el mal'') explicitan la intención hostil. El falso testigo ''tramó'' contra su hermano (Dt 19:19), los enemigos ''maquinaron'' contra el salmista (Sal 31:13) y el malvado ''maquina'' contra el justo (Sal 37:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94570, 'spa', 'considerar o contemplar', 'Considerar, contemplar o evaluar cuidadosamente antes de actuar, un sentido cognitivo neutral de sopesar opciones. Se encuentra únicamente en el retrato de la mujer virtuosa que ''considera'' un campo y luego lo compra (Pr 31:16). El español ''considera'' capta la cualidad deliberativa, distinguiendo la evaluación reflexiva tanto de la resolución firme como de la maquinación maliciosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94576, 'spa', 'Tiempos señalados', 'Describe «tiempos señalados» en tres contextos administrativos o cúlticos del período postexílico (Esd 10:14; Neh 10:34; 13:31). Las glosas multilingües (señalados, appointed) reflejan uniformemente fijeza temporal y planificación. El término denota tiempos establecidos por autoridad, ya sea para asambleas legales o para observancias rituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94578, 'spa', 'Tiempo señalado', 'Un tiempo designado o fijo, establecido por acuerdo humano u ordenamiento divino. Nehemías lo emplea para el plazo que negoció con el rey Artajerjes (Neh 2:6). Eclesiastés 3:1 lo usa para la ''estación'' divinamente dispuesta de cada actividad humana. Ester 9:27, 31 fija los ''tiempos'' anuales para celebrar Purim. Los cognados árabe zamān y arameo זְמַן confirman su amplia difusión semítica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94579, 'spa', 'Sustantivo arameo que designa un tiempo definido, una ocasión señalada o una est', 'Sustantivo arameo que designa un tiempo definido, una ocasión señalada o una estación, empleado exclusivamente en las secciones arameas de Daniel y Esdras. Abarca ocasiones específicas (Dn 3:7-8 ''en el momento en que''; 4:36 ''en aquel tiempo''; Esd 5:3), demoras solicitadas (Dn 2:16 ''concederle tiempo''), la soberanía divina sobre el orden temporal (Dn 2:21 ''Él cambia los tiempos y las estaciones'') y la fórmula escatológica ''un tiempo, tiempos y medio tiempo'' (Dn 7:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94585, 'spa', 'Cantar alabanzas, hacer música en adoración a Dios, abarcando tanto la melodía v', 'Cantar alabanzas, hacer música en adoración a Dios, abarcando tanto la melodía vocal como el acompañamiento instrumental. Uso exclusivamente poético, concentrado en los Salmos (más de 40 de 45 ocurrencias), con la primera aparición en el cántico de victoria de Débora (Jue 5:3) y un paralelo en la acción de gracias de David (2 S 22:50). Gobierna tanto imperativos de adoración comunitaria (''cantad alabanzas a YHWH'', Sal 9:11; 30:4) como declaraciones en primera persona (''cantaré alabanzas a tu nombre'', Sal 18:49; 57:9; 108:3). El sustantivo emparentado מִזְמוֹר (''salmo, melodía'') confirma la integración de voz e instrumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94609, 'spa', 'Poda de viñas', 'Designa la práctica agrícola de podar vides en tres contextos: mandato (Lev 25:3), prohibición sabática (Lev 25:4) y abandono por juicio (Is 5:6, forma pasiva). Las traducciones multilingües reflejan uniformemente la acción vitícola. El término evoca el ciclo del cuidado agrícola y su interrupción, ya sea por ley o por juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94611, 'spa', 'Música instrumental', 'Música o canto instrumental: el sonido colectivo de una orquesta o conjunto. Las cuatro apariciones se dan en la fórmula solemne de adoración ante la imagen de Nabucodonosor (Dan 3:5, 7, 10, 15), donde ''toda clase de música'' corona la lista de instrumentos individuales. La forma enfática aramea זְמָרָא corresponde al hebreo זִמְרָה y al conocido verbo זָמַר (''cantar alabanza'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94613, 'spa', 'Cántico de alabanza', 'Cántico, melodía o música ofrecida en adoración y alabanza. El término abarca tanto la ejecución instrumental —como en Am 5:23, donde se empareja con el sonido de las arpas— como la celebración vocal o musical en general, como en Sal 81:2 (''Entonad un cántico y tocad el pandero''). La evidencia interlingüística converge en la alabanza musical: ''cántico'', ''cantique'', ''ein Lied''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94615, 'spa', 'Zimri', 'El nombre propio Zimri (זִמְרִי), portado por múltiples figuras del Antiguo Testamento: (a) un príncipe simeonita ejecutado por Finees por introducir una mujer madianita en el campamento israelita (Nm 25:14); (b) el quinto rey del reino del norte de Israel, que asesinó a Ela y reinó solo siete días antes de incendiar el palacio sobre sí mismo (1 R 16:9-18); (c) un nieto de Zéraj de Judá (1 Cr 2:6); y (d) un descendiente benjaminita de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94619, 'spa', 'Alabanza musical', 'Designa la alabanza musical en dos núcleos temáticos: Yahvé como «mi cántico» (Éx 15:2; Sal 118:14; Is 12:2) y la música instrumental o vocal en el culto (Sal 81:2; 98:5; cf. Am 5:23). Las traducciones multilingües subrayan la función celebrativa y litúrgica. El término evoca adoración comunitaria y gozosa, no lamento individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94620, 'spa', 'Clase o variedad', 'Designa variedades o clases en dos contextos: productos agrícolas (Sal 144:13, «de especie en especie» = de todo tipo) y especias aromáticas (2 Cr 16:14). Las traducciones multilingües reflejan uniformemente la diversidad categorial. El término transmite plenitud mediante la enumeración de tipos, una abundancia que trasciende las categorías individuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94621, 'spa', 'Clase o tipo', 'Clase, tipo o categoría, específicamente de cosas agrupadas por género. Las cuatro apariciones bíblicas se dan en la frase constructa ''clases de música'' (זְנֵי זְמָרָא) en Daniel 3:5, 7, 10, 15, cada vez enumerando el conjunto instrumental que ordena la postración ante la imagen. Las traducciones convergen en la noción de clasificación: ''tipo de'', ''kinds of'', ''Art''.');